import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Check, X } from "lucide-react";

const roles = [
    { name: "admin", label: "Administrator", description: "Full system access, staff management, audit logs." },
    { name: "vet", label: "Veterinarian", description: "Medical records, prescriptions, surgeries, appointments." },
    { name: "assistant", label: "Vet Assistant", description: "Patient intake, basic records, scheduling." },
    { name: "receptionist", label: "Receptionist", description: "Client management, scheduling, billing (basic)." },
];

const capabilities = [
    { name: "View Dashboard", admin: true, vet: true, assistant: true, receptionist: true },
    { name: "Manage Clients", admin: true, vet: true, assistant: true, receptionist: true },
    { name: "Manage Patients", admin: true, vet: true, assistant: true, receptionist: true },
    { name: "Medical Records", admin: true, vet: true, assistant: true, receptionist: false },
    { name: "Full Billing", admin: true, vet: false, assistant: false, receptionist: true },
    { name: "Manage Staff", admin: true, vet: false, assistant: false, receptionist: false },
    { name: "View Audit Logs", admin: true, vet: false, assistant: false, receptionist: false },
    { name: "System Settings", admin: true, vet: false, assistant: false, receptionist: false },
];

export default function PermissionsPage() {
    return (
        <div className="flex-1 space-y-4 p-8 pt-6">
            <div className="flex items-center justify-between">
                <h2 className="text-3xl font-bold tracking-tight">System Permissions</h2>
            </div>

            <div className="space-y-4">
                <div className="rounded-md border p-4 bg-muted/20">
                    <h3 className="text-lg font-medium mb-2">Role Definitions</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                        {roles.map(role => (
                            <div key={role.name} className="p-4 rounded-lg border bg-card">
                                <div className="flex items-center gap-2 mb-2">
                                    <Badge variant="outline" className="uppercase">{role.name}</Badge>
                                </div>
                                <h4 className="font-bold">{role.label}</h4>
                                <p className="text-sm text-muted-foreground mt-1">{role.description}</p>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="rounded-md border">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead className="w-[200px]">Capability</TableHead>
                                <TableHead className="text-center">Admin</TableHead>
                                <TableHead className="text-center">Vet</TableHead>
                                <TableHead className="text-center">Assistant</TableHead>
                                <TableHead className="text-center">Receptionist</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {capabilities.map((cap) => (
                                <TableRow key={cap.name}>
                                    <TableCell className="font-medium">{cap.name}</TableCell>
                                    <TableCell className="text-center">
                                        {cap.admin ? <Check className="h-4 w-4 mx-auto text-green-600" /> : <X className="h-4 w-4 mx-auto text-muted-foreground/30" />}
                                    </TableCell>
                                    <TableCell className="text-center">
                                        {cap.vet ? <Check className="h-4 w-4 mx-auto text-green-600" /> : <X className="h-4 w-4 mx-auto text-muted-foreground/30" />}
                                    </TableCell>
                                    <TableCell className="text-center">
                                        {cap.assistant ? <Check className="h-4 w-4 mx-auto text-green-600" /> : <X className="h-4 w-4 mx-auto text-muted-foreground/30" />}
                                    </TableCell>
                                    <TableCell className="text-center">
                                        {cap.receptionist ? <Check className="h-4 w-4 mx-auto text-green-600" /> : <X className="h-4 w-4 mx-auto text-muted-foreground/30" />}
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </div>
            </div>
        </div>
    );
}
